function formatDate(date) 
		{
	 		var d = new Date(date),
	 	month = '' + (d.getMonth() + 1),
	 	day = '' + d.getDate(),
	 	year = d.getFullYear();
	
	 		if (month.length < 2) 
	 		month = '0' + month;
	 		if (day.length < 2) 
	 		day = '0' + day;
	
	 		return [year, month, day].join('-');
		}
		
for(var i = 0 ; i<tw.local.searchCriteriaSearchBy.length;i++){
	if(tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.CIF)
		tw.local.searchCriteria.CIF = tw.local.cif;

	else if(tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.RequestType)
		tw.local.searchCriteria.requestType = tw.local.RequestType;

