		tw.local.searchCriteria.BPMRequestNo = tw.local.RequestNumber;

	else if(tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.InvoiceNumber)
		tw.local.searchCriteria.invoiceNo = tw.local.InvoiceNumber;

	else if(tw.local.searchCriteriaSearchBy[i].value == tw.epv.searchCriteria.BillOfLading)
		tw.local.searchCriteria.billOfLading = tw.local.BillOfLading;

