	}
	
	if(me.getSelectedItems()[i].name =="Currency العملة" )
	{
	
		${currency}.setVisible(true,true);
		
	}
	
	if(me.getSelectedItems()[i].name =="Document Amount كامل مبلغ العملية موضوع الموافقة" ){
	
		${documentAmountFrom}.setVisible(true,true);
		${documentAmountTo}.setVisible(true,true);
		
	}
	
	if(me.getSelectedItems()[i].name =="Amount Collectable by NBE اجمالى المبالغ المطلوب تحصيها" ){
	
