		${collectableAmountTo}.setVisible(true,true);
		
	}
	
	if(me.getSelectedItems()[i].name =="Outstanding Amount" ){
	
		${outstandingAmountFrom}.setVisible(true,true);
		${outstandingAmountTo}.setVisible(true,true);
		
	}
	
