.spark-ui {
 background: rgb(255, 255, 255);
 // width: 99%;
}
.CoachView.Panel>.panel.SPARKPanel {
border-collapse: separate;
border-spacing: 0;
box-shadow: 0px 0px 12px #001B5929!important;
border-top: 5px solid #00643e!important;
border-radius: 10px!important;
}

.panel-primary.panel-dark>.panel-heading {
background: transparent !important;
border-color: transparent;
color: #fff;
}

.panel-primary.panel-dark {
border-color: transparent!important;
}
.panel-primary.panel-dark > .panel-heading .panel-title {
 color: rgb(0, 101, 71);
 font: normal normal 600 24px/45px Cairo;
}

.form-control {
 border-top-color: rgb(205, 205, 205);
 border-bottom-color: rgb(205,205,205);
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 padding: 12px 12px;
 color: #181A1D !important;
 background: #FFFFFF 0% 0% no-repeat padding-box;
 border: 1px solid #ddd;
 border-radius: 8px;
}
.SPARKWell .stat-cell .bg-icon {
 line-height: normal;
 height: 100%;
 overflow: hidden;
 // width: 97%;
 border-radius: inherit;
 box-shadow: 0px 0px 12px #001B5929!important;
 margin-bottom: 6px;
 border-radius: 10px!important;
