	 border-radius: 2px;
	 border-width: 0px;
}

.panel-group.panel-group-primary>.panel>.panel-heading>.accordion-toggle {
	 background: #fff;
	 color: #006547;
	 border-color: #fff;
	 padding: 15px;
	 border-radius: 10px!important;
}

