	else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.BillOfLading)
		tw.local.searchCriteria.billOfLading = tw.local.BillOfLading;

	else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.TradeFoReferenceNumber)
		tw.local.searchCriteria.tradeFoRefrenceNo = tw.local.TradeFoReferenceNumber;

	else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.RequestStatus)
		tw.local.searchCriteria.requestStatus = tw.local.RequestStatus;
////////////////
	else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.RequestDate)
	  tw.local.searchCriteria.requestDate = formatDate( tw.local.RequestDate);
	
	else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.Date){
	  tw.local.searchCriteria.dateFrom = formatDate( tw.local.dateFrom);
	  tw.local.searchCriteria.dateTo = formatDate( tw.local.dateTo);
	  }
	  else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.InstanceNumber){
	  tw.local.searchCriteria.instanceNumber = tw.local.instanceNumber;
	  }
	  else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.paymentTerms){
	  tw.local.searchCriteria.paymentTerms = tw.local.paymentTermSelect;
	  }
	  else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.Currency){
	  tw.local.searchCriteria.currency = tw.local.currency;
	  }
	  else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.DocumentAmount){
	  tw.local.searchCriteria.documentAmountFrom = tw.local.documentAmountFrom.toString();
	  tw.local.searchCriteria.documentAmountTo = tw.local.documentAmountTo.toString();
	  }
	   else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.CollectableAmount){
	  tw.local.searchCriteria.collectableAmountFrom = tw.local.collectableAmountFrom.toString();
	  tw.local.searchCriteria.collectableAmountTo = tw.local.collectableAmountTo.toString();
	  }
	     else if(tw.local.searchCriteriaSearchBy[i].value  == tw.epv.searchCriteria.OutstandingAmount){
	  tw.local.searchCriteria.outstandingAmountFrom = tw.local.outstandingAmountFrom.toString();
	  tw.local.searchCriteria.outstandingAmountTo = tw.local.outstandingAmountTo.toString();
	  }
	  
	else{}
}

