ns16:scriptTask.ns16:script:
tw.local.alertMessage = String(tw.error.data);
tw.local.displayErrorMsg = tw.local.alertMessage;
tw.local.displayErrorMsg != "" ? (tw.local.errorPanelVis = "EDITABLE") : (tw.local.errorPanelVis = "NONE");
tw.local.errorVis = "EDITABLE";

//tw.local.message = "";
//tw.local.validationMessage = "";
tw.local.displayErrorMsg = "";
tw.local.errorPanelVis = "NONE";
var mandatoryTriggered = false;
var tempLength = 0 ;
tw.system.coachValidation.clearValidationErrors();
//--------------------------------------------------------------------------------------------------------------------------------
if(!tw.local.searchCriteriaSearchBy ){
mandatory(tw.local.searchCriteriaSearchBy ,"tw.local.searchCriteriaSearchBy ","search By");

}

for(var i =0; i<tw.local.searchCriteriaSearchBy.length;i++){
	var field = tw.local.searchCriteriaSearchBy[i].value;
//
 	if (field == tw.epv.searchCriteria.CIF+"") {
		tw.local.searchField = tw.local.cif;
  		mandatory(tw.local.cif,"tw.local.cif","CIF");
  		if(tw.local.cif.length !=8)
  		{
  			tw.local.displayErrorMsg = "CIf must be 8 digits";
  			tw.system.coachValidation.addValidationError("tw.local.cif.", "CIf must be 8 digits");
  		}
//
//
	} else if (field === tw.epv.searchCriteria.RequestType+"") {
		tw.local.searchField = tw.local.RequestType;
  		mandatory(tw.local.RequestType,"tw.local.RequestType","Request Type");

	} else if (field === tw.epv.searchCriteria.BPMRequestNumber+"") {
		tw.local.searchField = tw.local.RequestNumber;
  		mandatory(tw.local.RequestNumber,"tw.local.RequestNumber","BPM Request Number");
  		validateReqNum(tw.local.RequestNumber,"tw.local.RequestNumber","Please enter a valid Request Number");
 
	} else if (field === tw.epv.searchCriteria.RequestStatus+"") {
		tw.local.searchField = tw.local.RequestStatus;
  		mandatory(tw.local.RequestStatus,"tw.local.RequestStatus","Request Status");

	} else if (field === tw.epv.searchCriteria.RequestDate+"") {

		mandatory(tw.local.RequestDate,"tw.local.RequestDate","Request Date");
//  
	} else if (field === tw.epv.searchCriteria.InvoiceNumber+"") {
		tw.local.searchField = tw.local.InvoiceNumber;
  		mandatory(tw.local.InvoiceNumber,"tw.local.InvoiceNumber","Invoice Number");
  
	} else if (field === tw.epv.searchCriteria.BillOfLading+"") {
		tw.local.searchField = tw.local.BillOfLading;
  		mandatory(tw.local.BillOfLading,"tw.local.BillOfLading","Bill Of Lading");
  
	} else if (field === tw.epv.searchCriteria.TradeFoReferenceNumber+"") {
		tw.local.searchField = tw.local.TradeFoReferenceNumber;
  		mandatory(tw.local.TradeFoReferenceNumber,"tw.local.TradeFoReferenceNumber","Trade Fo Reference Number")
	}
	else if (field === tw.epv.searchCriteria.Date+"") {
  		mandatory(tw.local.dateFrom,"tw.local.dateFrom","Date From");
  		mandatory(tw.local.dateTo,"tw.local.dateTo","Date To");
	}
	else if (field === tw.epv.searchCriteria.InstanceNumber+"") {
  		mandatory(tw.local.instanceNumber,"tw.local.instanceNumber","BPM Instance Number");
  		
	}
	else if (field === tw.epv.searchCriteria.paymentTerms+"") {
  		mandatory(tw.local.paymentTermSelect,"tw.local.paymentTermSelect", "Payment Terms");
  		
  		
	}
	else if (field === tw.epv.searchCriteria.Currency+"") {
  		mandatory(tw.local.currency,"tw.local.currency", "Currency");
  		
  		
	}
	else if (field === tw.epv.searchCriteria.DocumentAmount+"") {
  		mandatory(tw.local.documentAmountFrom,"tw.local.documentAmountFrom","Document Amount From");
  		mandatory(tw.local.documentAmountTo,"tw.local.documentAmountTo","Document Amount To");
	}
	else if (field === tw.epv.searchCriteria.CollectableAmount+"") {
  		mandatory(tw.local.collectableAmountFrom,"tw.local.collectableAmountFrom","Collectable Amount From");
  		mandatory(tw.local.collectableAmountTo,"tw.local.collectableAmountTo","Collectable Amount To");
	}
	else if (field === tw.epv.searchCriteria.OutstandingAmount+"") {
  		mandatory(tw.local.outstandingAmountFrom,"tw.local.outstandingAmountFrom","Outstanding Amount From");
  		mandatory(tw.local.outstandingAmountTo,"tw.local.outstandingAmountTo","Outstanding Amount To");
	}

}
//-----------------------------------------------------------------------------------------------------------------------

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
//	fromMandatory && mandatoryTriggered ? "" : tw.local.message += "<li dir='rtl'>" + validationMessage + "</li>";
}



/*
* ==================================================================================================================
*
* Add a coach validation error if the field is null 'Mandatory'
*	
* EX:	notNull(tw.local.name , 'tw.local.name')
*
* ==================================================================================================================
*/

function mandatory(field , fieldName,name)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , "This Field Is Mandatory" , "Mandatory Fields" , true);
		tw.local.displayErrorMsg += "<li>"+"Kindly enter the mandatory field "+name+"</li>";
		mandatoryTriggered = true;
		return false;
	}
	else
	{
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , "This Field Is Mandatory" , "Mandatory Fields" , true);
					tw.local.displayErrorMsg += "<li>"+"Kindly enter the mandatory field "+name+"</li>";
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , "This Field Is Mandatory" , "Mandatory Fields" , true);
					tw.local.displayErrorMsg +="<li>"+"Kindly enter the mandatory field "+name+"</li>";
					mandatoryTriggered = true;
					return false;
				}
				break;
		}
	}
	return true;
}

//--------------------------------------------------------------------
function validateReqNum(field,fieldName,message) {
	var regex = /^(\d{14}(?:-\d+)?)$/;
	if (!regex.test(field)){
		addError(fieldName , message);
		return false;
	}else{
		return true;
	}
}


